<?php
class CC_Rating { public static function init(){} public static function get($city){ global $wpdb; $t=CC_DB::table(); $rows=$wpdb->get_results($wpdb->prepare("SELECT stars,COUNT(*) n FROM $t WHERE city_id=%d GROUP BY stars",$city)); $dist=array_fill(1,7,0); foreach($rows as $r)$dist[(int)$r->stars]=(int)$r->n; $count=(int)get_post_meta($city,'cc_rating_count',true); return array('average'=>(float)get_post_meta($city,'cc_rating_avg',true),'count'=>$count,'distribution'=>array_values($dist),'user_rating'=>is_user_logged_in()?(int)$wpdb->get_var($wpdb->prepare("SELECT stars FROM $t WHERE city_id=%d AND user_id=%d",$city,get_current_user_id())):0); } }
